=== api.ts
import { API_URL } from "./const";
import { TLoginSchema } from "./schemas/LoginSchema";
import type {
  APILoginResponseSuccess,
  Document,
  FetchStreamOptions,
  StreamChunk,
} from "./types/api";

type LoginReturnSuccess = {
  success: true;
  message?: never;
  data: TLoginSchema;
};

interface LoginReturnFailed {
  success: false;
  message?: string;
  data?: never;
}

type LoginReturn = LoginReturnSuccess | LoginReturnFailed;

export async function login(
  user_id: string,
  remember: boolean = false,
): Promise<LoginReturn> {
  try {
    const url = API_URL + "/api/auth/login";
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ user_id }),
    });

    if (!response.ok) {
      return {
        success: false,
        message: "Login failed",
      };
    } else {
      const data = {
        ...((await response.json()) as APILoginResponseSuccess),
        remember,
      };
      return {
        success: true,
        data,
      };
    }
  } catch (e) {
    console.error(
      "Error logging in:",
      (e as Error).message,
    );
    return {
      success: false,
      message: (e as Error).message,
    };
  }
}

export async function chat({
  data,
  onMessage,
  onError,
}: FetchStreamOptions): Promise<void> {
  try {
    const url = API_URL + "/api/chat/";

    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/x-ndjson",
      },
      credentials: "include",
      body: JSON.stringify(data),
    });

    if (!response.ok) {
      throw new Error(
        `Errore API: ${response.status}, ${await response.text()}`,
      );
    }

    if (!response.body) {
      throw new Error("Stream non disponibile");
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    try {
      while (true) {
        const { done, value } = await reader.read();

        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        const lines = buffer.split("\n");
        buffer = lines.pop() ?? "";

        for (const line of lines) {
          if (line.trim()) {
            onMessage(JSON.parse(line) as StreamChunk);
          }
        }
      }

      buffer += decoder.decode();

      if (buffer.trim()) {
        onMessage(JSON.parse(buffer) as StreamChunk);
      }
    } finally {
      reader.releaseLock();
    }
  } catch (error) {
    const normalizedError =
      error instanceof Error
        ? error
        : new Error("Errore sconosciuto");

    if (onError) {
      onError(normalizedError);
    } else {
      throw normalizedError;
    }
  }
}

type UploadReturnSuccess = {
  success: true;
  message: string;
  documents?: Document[];
  detail?: never;
};

interface UploadReturnFailed {
  success: false;
  message?: never;
  documents?: never;
  detail?: string;
}

type UploadReturn =
  | UploadReturnSuccess
  | UploadReturnFailed;

export async function uploadDocuments(
  files: File[],
): Promise<UploadReturn> {
  try {
    //const session = await getSession();

    //if (!session) throw new Error("Authentication failed!");

    //const cookie = session.user_id;

    const formData = new FormData();

    files.forEach((file) => {
      formData.append("files", file);
    });

    const url = API_URL + "/api/documents/";

    const response = await fetch(url, {
      method: "POST",
      credentials: "include",
      body: formData,
    });

    const msg: UploadReturn = await response.json();
    console.log(msg);

    if (!response.ok) {
      console.error(msg.detail);
      throw new Error(`Upload failed: `);
    }

    return {
      success: true,
      ...msg,
    };
  } catch (e) {
    console.error(
      "Error uploading documents :",
      (e as Error).message,
    );
    return {
      success: false,
      detail: (e as Error).message,
    };
  }
}

