  .file()
  .max(MAX_FILE_SIZE, "Il file non puÃ² superare i 10 MB")
  .mime(
    ["application/pdf"],
    "Sono consentiti solo file PDF",
  );

export const PDFSchema = z.object({
  files: z
    .array(pdfFileSchema)
    .min(1, "Seleziona almeno un PDF")
    .max(
      MAX_FILES,
      `Puoi caricare massimo ${MAX_FILES} file`,
    ),
});

