import { FieldErrors } from "react-hook-form";
import { uploadDocuments } from "../api";
import { ZodParser } from "../schemas/parser";
import {
  PDFSchema,
  TPDFSchema,
} from "../schemas/PDFSchema";

interface UploadSuccess {
  success: true;
  formErrors?: never;
  message?: string;
}

interface UploadFailed {
  success: false;
  formErrors?: FieldErrors<TPDFSchema>;
  message?: string;
}

type UploadState = UploadSuccess | UploadFailed;

export async function act_UploadDocuments(
  previousState: UploadState | null,
  data: TPDFSchema,
): Promise<UploadState | null> {
  const parsed = ZodParser(data, PDFSchema);

  if (!parsed.success) {
    return {
      success: false,
      formErrors: parsed.result,
    };
  }
  const { files } = parsed.result;

  const result = await uploadDocuments(files);

  return result;
}
