export async function chat({
  data,
  onMessage,
  onError,
}: FetchStreamOptions): Promise<void> {
  try {
    const url = API_URL + "/api/chat/";

    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/x-ndjson",
      },
      credentials: "include",
      body: JSON.stringify(data),
    });

    if (!response.ok) {
      throw new Error(
        `Errore API: ${response.status}, ${await response.text()}`,
      );
    }

    if (!response.body) {
      throw new Error("Stream non disponibile");
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    try {
      while (true) {
        const { done, value } = await reader.read();

        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        const lines = buffer.split("\n");
        buffer = lines.pop() ?? "";

        for (const line of lines) {
          if (line.trim()) {
            onMessage(JSON.parse(line) as StreamChunk);
          }
        }
      }

      buffer += decoder.decode();

      if (buffer.trim()) {
        onMessage(JSON.parse(buffer) as StreamChunk);
      }
    } finally {
      reader.releaseLock();
    }
  } catch (error) {
    const normalizedError =
      error instanceof Error
        ? error
        : new Error("Errore sconosciuto");

    if (onError) {
      onError(normalizedError);
    } else {
      throw normalizedError;
    }
  }
}

