function isStreamEvent(value: unknown): value is StreamEvent {
  if (
    typeof value !== "object" ||
    value === null ||
    !("type" in value)
  ) {
    return false;
  }

  switch (value.type) {
    case "content":
      return "delta" in value && typeof value.delta === "string";
    case "citations":
      return (
        "references" in value && Array.isArray(value.references)
      );
    case "error":
      return (
        "message" in value && typeof value.message === "string"
      );
    default:
      return false;
  }
}

function parseStreamLine(line: string): StreamEvent {
  let parsed: unknown;

  try {
    parsed = JSON.parse(line);
  } catch {
    throw new Error("Risposta dello stream non valida");
  }

  if (!isStreamEvent(parsed)) {
    throw new Error("Evento dello stream non riconosciuto");
  }

  return parsed;
}

async function readErrorDetail(
  response: Response,
  fallback: string,
): Promise<string> {
  try {
    const body: unknown = await response.json();

    if (
      typeof body === "object" &&
      body !== null &&
      "detail" in body &&
      typeof body.detail === "string"
    ) {
      return body.detail;
    }
  } catch {
    // Non-JSON error body: use the fallback.
  }

  return `${fallback} (${response.status})`;
}

async function getJSON<T>(
  path: string,
  signal?: AbortSignal,
): Promise<T> {
  const response = await fetch(API_URL + path, {
    credentials: "include",
    headers: { Accept: "application/json" },
    signal,
  });

  if (!response.ok) {
    throw new Error(
      await readErrorDetail(
        response,
        "Errore durante la comunicazione con l'API",
      ),
    );
  }

  return (await response.json()) as T;
}

export async function chat({
  data,
  onMessage,
  onError,
  signal,
}: FetchStreamOptions): Promise<void> {
  try {
    const url = API_URL + ENDPOINTS.chat;

    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/x-ndjson",
      },
      credentials: "include",
      body: JSON.stringify(data),
      signal,
    });

    if (!response.ok) {
      throw new Error(
        `Errore API: ${response.status}, ${await response.text()}`,
      );
    }

    if (!response.body) {
      throw new Error("Stream non disponibile");
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    const handleLine = (line: string) => {
      if (!line.trim()) return;

      const event = parseStreamLine(line);

      if (event.type === "error") {
        throw new Error(event.message);
      }

      onMessage(event);
    };

    try {
      while (true) {
        const { done, value } = await reader.read();

        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        const lines = buffer.split("\n");
        buffer = lines.pop() ?? "";

        lines.forEach(handleLine);
      }

      buffer += decoder.decode();
      handleLine(buffer);
    } finally {
      reader.releaseLock();
    }
  } catch (error) {
    const normalizedError =
      error instanceof Error
        ? error
        : new Error("Errore sconosciuto");

    if (onError) {
      onError(normalizedError);
    } else {
      throw normalizedError;
    }
  }
}

// The backend lists chats oldest first, so the newest ones sit on the last page.
const CHATS_PAGE_SIZE = 100;

export async function listChats(
  signal?: AbortSignal,
): Promise<APIChat[]> {
  const chats: APIChat[] = [];

  for (let offset = 0; ; offset += CHATS_PAGE_SIZE) {
    const page = await getJSON<APIChat[]>(
      `${ENDPOINTS.chat}?limit=${CHATS_PAGE_SIZE}&offset=${offset}`,
      signal,
    );

    chats.push(...page);

    if (page.length < CHATS_PAGE_SIZE) return chats;
  }
}

export function getChat(
  chatId: string,
  signal?: AbortSignal,
): Promise<APIChat> {
  return getJSON<APIChat>(
    ENDPOINTS.chat + encodeURIComponent(chatId),
    signal,
  );
}

