{
  "file_text": "import type {
  DocumentReference,
  DocumentReferenceBoundingRegion,
} from "../types/chat";

// Coordinate system assumptions (verified against backend/tests/bbox_visualization.py):
// - `rects_in` entries are [x, y, width, height] in inches.
// - The origin is the top-left corner of the page and y grows downwards,
//   the same orientation used by the browser, so no axis flip is needed.
// - Pages are measured as rendered (rotation applied), and 1 inch is
//   72 PDF points.
// Every conversion goes through the helpers below: rectangles become
// percentages of the page size, so any overlay stretched over the rendered
// page keeps its alignment at every zoom level and container width.

export const PDF_POINTS_PER_INCH = 72;

export type Rect = readonly [
  x: number,
  y: number,
  width: number,
  height: number,
];

export type PageSize = { width: number; height: number };

export type PercentBox = {
  left: number;
  top: number;
  width: number;
  height: number;
};

export function pointsToInches(points: number): number {
  return points / PDF_POINTS_PER_INCH;
}

export function isRect(value: unknown): value is Rect {
  return (
    Array.isArray(value) &&
    value.length === 4 &&
    value.every(
      (n) => typeof n === "number" && Number.isFinite(n),
    ) &&
    value[2] > 0 &&
    value[3] > 0
  );
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

// Box of `rect` relative to the page, in percent, limited to the page area.
export function rectToPercentBox(
  rect: Rect,
  page: PageSize,
): PercentBox {
  const [x, y, width, height] = rect;
  const left = clamp((x / page.width) * 100, 0, 100);
  const top = clamp((y / page.height) * 100, 0, 100);

  return {
    left,
    top,
    width: clamp((width / page.width) * 100, 0, 100 - left),
    height: clamp((height / page.height) * 100, 0, 100 - top),
  };
}

// Valid rectangles of the regions that belong to `pageNumber`.
export function rectsForPage(
  regions: readonly DocumentReferenceBoundingRegion[],
  pageNumber: number,
): Rect[] {
  return regions
    .filter((region) => region.page_number === pageNumber)
    .flatMap((region) => region.rects_in.filter(isRect));
}

// Page to show first for a reference: the page of its citation, otherwise the
// first page that has a region.
export function referencePage(reference: DocumentReference): number {
  if (Number.isInteger(reference.page_number) && reference.page_number > 0) {
    return reference.page_number;
  }

  return (
    reference.bounding_regions.find(
      (region) => region.page_number > 0,
    )?.page_number ?? 1
  );
}

export function hasHighlights(reference: DocumentReference): boolean {
  return reference.bounding_regions.some(
    (region) => rectsForPage([region], region.page_number).length > 0,
  );
}
