import {
  pointsToInches,
  type PageSize,
  type Rect,
} from "@/lib/pdf/geometry";
import { errorMessage } from "@/lib/utils";
import type { PDFDocumentProxy, PDFPageProxy } from "pdfjs-dist";
import { useEffect, useRef, useState } from "react";
import { HighlightOverlay } from "./HighlightOverlay";

// Keeps very large zoom levels from allocating huge canvases.
const MAX_CANVAS_WIDTH = 4096;

type LoadedPage = {
  pageNumber: number;
  page: PDFPageProxy;
  size: PageSize;
};

type PageStatus =
  | { status: "loading" }
  | { status: "ready" }
  | { status: "error"; message: string };

// Renders one page of `pdf` at `width` CSS pixels, with its highlights.
export function PdfPage({
  pdf,
  pageNumber,
  width,
  highlights,
}: {
  pdf: PDFDocumentProxy;
  pageNumber: number;
  width: number;
  highlights: readonly Rect[];
}) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [loaded, setLoaded] = useState<LoadedPage | null>(null);
  const [rendered, setRendered] = useState<number | null>(null);
  const [failure, setFailure] = useState<{
    pageNumber: number;
    message: string;
  } | null>(null);

  useEffect(() => {
    let cancelled = false;

    pdf.getPage(pageNumber).then(
      (page) => {
        if (cancelled) return;

        const viewport = page.getViewport({ scale: 1 });

        setLoaded({
          pageNumber,
          page,
          size: {
            width: pointsToInches(viewport.width),
            height: pointsToInches(viewport.height),
          },
        });
      },
      (error: unknown) => {
        if (!cancelled) {
          setFailure({ pageNumber, message: errorMessage(error) });
        }
      },
    );

    return () => {
      cancelled = true;
    };
  }, [pdf, pageNumber]);

  useEffect(() => {
    const canvas = canvasRef.current;

    if (!loaded || !canvas || width <= 0) return;

    const { page, pageNumber: renderedPage } = loaded;
    const base = page.getViewport({ scale: 1 });
    const pixelRatio = Math.min(
      window.devicePixelRatio || 1,
      MAX_CANVAS_WIDTH / width,
    );
    const viewport = page.getViewport({
      scale: (width / base.width) * pixelRatio,
    });

    canvas.width = Math.floor(viewport.width);
    canvas.height = Math.floor(viewport.height);

    const task = page.render({ canvas, viewport });

    task.promise.then(
      () => setRendered(renderedPage),
      (error: unknown) => {
        if (
          error instanceof Error &&
          error.name === "RenderingCancelledException"
        ) {
          return;
        }

        setFailure({
          pageNumber: renderedPage,
          message: errorMessage(error),
        });
      },
    );

    return () => task.cancel();
  }, [loaded, width]);

  const status: PageStatus =
    failure?.pageNumber === pageNumber
      ? { status: "error", message: failure.message }
      : loaded?.pageNumber === pageNumber &&
          rendered === pageNumber
        ? { status: "ready" }
        : { status: "loading" };

  // The canvas keeps showing the previous page until the new one is ready;
  // highlights are only drawn when they belong to the page on screen.
  const showOverlay =
    status.status === "ready" && loaded?.pageNumber === pageNumber;

  const aspectRatio = loaded
    ? loaded.size.width / loaded.size.height
    : 1 / Math.SQRT2;

  const firstHighlight = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!showOverlay) return;

    firstHighlight.current
      ?.querySelector("[data-highlight]")
      ?.scrollIntoView({ block: "center", inline: "nearest" });
